5 | /**
6 |  * shouldSpeak(secondsLeft, totalSecs, intervalMins)
7 |  * Returns true when:
8 |  *   - intervalMins > 0
9 |  *   - 0 < secondsLeft < totalSecs  (not at the very start or very end)
10 |  *   - secondsLeft is an exact multiple of intervalMins * 60
11 |  */
12 | function shouldSpeak(secondsLeft, totalSecs, intervalMins) {
13 | 	if (intervalMins <= 0) return false;
14 | 	if (secondsLeft <= 0 || secondsLeft >= totalSecs) return false;
15 | 	var intervalSecs = intervalMins * 60;
16 | 	return secondsLeft % intervalSecs === 0;
17 | }
18 | 
19 | /**
20 |  * reminderText(secondsLeft, round)
21 |  * round: "focus" | "short" | "long"
22 |  * Returns e.g. "10 minutes left in your focus round"
23 |  *             "1 minute left in your short break"
24 |  */
25 | function reminderText(secondsLeft, round) {
26 | 	var mins = Math.floor(secondsLeft / 60);
27 | 	var unit = mins === 1 ? "minute" : "minutes";
28 | 	var label;
29 | 	if (round === "focus") {
30 | 		label = "focus round";
31 | 	} else if (round === "short") {
32 | 		label = "short break";
33 | 	} else {
34 | 		label = "long break";
35 | 	}
36 | 	return mins + " " + unit + " left in your " + label;
37 | }
38 | 
39 | /**
40 |  * transitionText(nextRound)
41 |  * nextRound: "focus" | "short" | "long"
42 |  */
43 | function transitionText(nextRound) {
44 | 	if (nextRound === "short") {
45 | 		return "Focus round done. Time for a short break.";
46 | 	}
47 | 	if (nextRound === "long") {
48 | 		return "Focus round done. Time for a long break.";
49 | 	}
50 | 	return "Break's over. Back to focus.";
51 | }
52 | 
53 | /**
54 |  * speak(text, synth)
55 |  * synth: window.speechSynthesis (or undefined/null when unavailable)
56 |  * Returns false when synth is missing; cancels any queued speech, speaks text, returns true.
57 |  */
58 | function speak(text, synth) {
59 | 	if (!synth) return false;
60 | 	synth.cancel();
61 | 	var utterance = new SpeechSynthesisUtterance(text);
62 | 	synth.speak(utterance);
63 | 	return true;
64 | }
