4 | 	/**
5 | 	 * Sanitize a free-text note.
6 | 	 *
7 | 	 * @param {*}      raw    - Raw value (expected string).
8 | 	 * @param {number} maxLen - Maximum length (default 280).
9 | 	 * @returns {string} Trimmed, newlines collapsed to spaces, truncated to maxLen.
10 | 	 */
11 | 	function sanitizeNote(raw, maxLen) {
12 | 		if (typeof raw !== "string") return "";
13 | 		if (typeof maxLen !== "number") maxLen = 280;
14 | 		// Collapse all whitespace runs (including newlines) to a single space, then trim
15 | 		var s = raw.replace(/\s+/g, " ").trim();
16 | 		if (s.length > maxLen) s = s.slice(0, maxLen);
17 | 		return s;
18 | 	}
