20 | 	/**
21 | 	 * Extract the note string from a record, guarding absent/non-string m.
22 | 	 *
23 | 	 * @param {object} record
24 | 	 * @returns {string}
25 | 	 */
26 | 	function noteFromRecord(record) {
27 | 		if (record && typeof record.m === "string" && record.m.length > 0) {
28 | 			return record.m;
29 | 		}
30 | 		return "";
31 | 	}
32 | 
33 | 	/**
34 | 	 * Return a NEW record with m set to the sanitized note, or m removed when the
35 | 	 * sanitized note is empty. Never mutates the input.
36 | 	 *
37 | 	 * @param {object} record
38 | 	 * @param {string} note
39 | 	 * @returns {object}
40 | 	 */
41 | 	function withNote(record, note) {
42 | 		var sanitized = sanitizeNote(note);
43 | 		var copy = {};
44 | 		var keys = Object.keys(record);
45 | 		for (var i = 0; i < keys.length; i++) {
46 | 			if (keys[i] !== "m") {
47 | 				copy[keys[i]] = record[keys[i]];
48 | 			}
49 | 		}
50 | 		if (sanitized.length > 0) {
51 | 			copy.m = sanitized;
52 | 		}
53 | 		return copy;
54 | 	}
