420 | function initNoise() {
421 | 	if (!audioCtx) {
422 | 		audioCtx = new AudioContext();
423 | 	}
424 | 	const bufferSize = audioCtx.sampleRate * 3;
425 | 	const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
426 | 	let data = buffer.getChannelData(0);
427 | 
428 | 	for (let i = 0; i < bufferSize; i++) {
429 | 		data[i] = Math.random() * 2 - 1;
430 | 	}
431 | 
432 | 	noiseSource = audioCtx.createBufferSource();
433 | 	noiseSource.buffer = buffer;
434 | 
435 | 	gain = audioCtx.createGain();
436 | 	gain.gain = volume / 100;
437 | 
438 | 	noiseSource.connect(gain);
439 | 	gain.connect(audioCtx.destination);
440 | }
