442 | volumeSlider.addEventListener("input", () => {
443 | 	volume = parseFloat(volumeSlider.value);
444 | 	volumeValue.textContent = volume;
445 | 	if (volume === 0) {
446 | 		volumeContainer.classList.add("muted");
447 | 	} else {
448 | 		volumeContainer.classList.remove("muted");
449 | 	}
450 | 	if (gain) gain.gain.linearRampToValueAtTime(volume / 100, audioCtx.currentTime);
451 | 	localStorage.setItem("pomo-audio-volume", volume);
452 | });
