454 | function playNoise() {
455 | 	noiseSource.loop = true;
456 | 	noiseSource.start();
457 | 	isWhiteNoiseRunning = true;
458 | }
459 | 
460 | function stopNoise() {
461 | 	noiseSource.stop();
462 | 	isWhiteNoiseRunning = false;
463 | 	isFadingOut = false;
464 | }
465 | 
466 | function fadeOut() {
467 | 	if (!isWhiteNoiseRunning) return;
468 | 	isFadingOut = true;
469 | 	gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 1);
470 | 	noiseTimeout = setTimeout(stopNoise, 1000);
471 | }
472 | 
473 | function fadeIn() {
474 | 	clearTimeout(noiseTimeout);
475 | 	if (!isFadingOut) {
476 | 		initNoise();
477 | 		gain.gain.setValueAtTime(0, audioCtx.currentTime);
478 | 		gain.gain.linearRampToValueAtTime(volume / 100, audioCtx.currentTime + 1);
479 | 		playNoise(0);
480 | 	} else {
481 | 		gain.gain.setValueAtTime(gain.gain.value, audioCtx.currentTime);
482 | 		gain.gain.linearRampToValueAtTime(volume / 100, audioCtx.currentTime + 1);
483 | 	}
484 | }
