1082 | 	if (!(timeValue === "all")) {
1083 | 		if (parseInt(timeValue) === 0) {
1084 | 			// Today
1085 | 			// Get the current date without the time component
1086 | 			const currentDate = new Date();
1087 | 			currentDate.setHours(0, 0, 0, 0);
1088 | 
1089 | 			// Calculate the start and end timestamps for the current day
1090 | 			const startOfDay = currentDate.getTime();
1091 | 			const endOfDay = startOfDay + 24 * 60 * 60 * 1000;
1092 | 
1093 | 			rec = rec.filter((r) => {
1094 | 				// Check if the task is within the current day
1095 | 				return r.d >= startOfDay && r.d < endOfDay && filteredTasks.has(r.n);
1096 | 			});
1097 | 		} else {
1098 | 			let tt = Date.now() - parseInt(timeValue) * 24 * 60 * 60 * 1000;
1099 | 			rec = rec.filter((r) => r.d >= tt && filteredTasks.has(r.n));
1100 | 		}
1101 | 	}
1102 | 	let charts = [];
1103 | 	let maxvalue = 0;
1104 | 	let minRoundValue = 0;
1105 | 	let maxRoundValue = 0;
1106 | 	let totalValue = 0;
