1108 | 	let dayTimes = new Array(7).fill(0);
1109 | 	let monthTimes = new Array(12).fill(0);
1110 | 	for (let task of filteredTasks) {
1111 | 		let chart = {
1112 | 			t: 0,
1113 | 			task: task,
1114 | 			n: 0,
1115 | 		};
1116 | 		rec.filter((r) => r.n === task).forEach((r) => {
1117 | 			chart.t += r.t;
1118 | 			totalValue += r.t;
1119 | 			let d = new Date(r.d);
1120 | 			hourlyTimes[Math.floor(d.getHours() / 6)] += r.t;
1121 | 			dayTimes[d.getDay()] += r.t;
1122 | 			monthTimes[d.getMonth()] += r.t;
1123 | 			chart.n++;
1124 | 			if (minRoundValue === 0) {
1125 | 				minRoundValue = r.t;
1126 | 			} else {
1127 | 				minRoundValue = minRoundValue > r.t ? r.t : minRoundValue;
1128 | 			}
1129 | 			maxRoundValue = maxRoundValue < r.t ? r.t : maxRoundValue;
1130 | 		});
1131 | 		maxvalue = maxvalue < chart.t ? chart.t : maxvalue;
