1284 | function hmstrFull(t) {
1285 | 	let r = hmstr(t)
1286 | 		.split(":")
1287 | 		.map((i) => parseInt(i));
1288 | 	if (r[0] === 0) return r[1] + " Minutes";
1289 | 	if (r[1] === 0) return r[0] + " Hour" + (r[0] === 1 ? "" : "s");
1290 | 	return `${r[0]} Hour${r[0] > 1 ? "s" : ""} & ${r[1]} Minute${r[1] > 1 ? "s" : ""}`;
1291 | }
